import React, { useState, useEffect } from 'react';

// Simulated data generation functions
const generateDummyData = () => {
  // Generate focus and break periods for a day
  const focusMinutes = Math.floor(Math.random() * 240) + 120; // 2-6 hours
  const breakMinutes = Math.floor(Math.random() * 120) + 60; // 1-3 hours

  // Create timeline intervals
  const intervals = [];
  let currentTime = new Date();
  currentTime.setHours(9, 0, 0, 0); // Start at 9 AM

  // Create 4-8 alternating focus/break periods
  const periodCount = Math.floor(Math.random() * 5) + 4;
  let isFocus = true;

  for (let i = 0; i < periodCount; i++) {
    const startTime = new Date(currentTime);
    const duration = Math.floor(Math.random() * (isFocus ? 90 : 45)) + (isFocus ? 30 : 15); // Focus: 30-120min, Break: 15-60min
    currentTime = new Date(currentTime.getTime() + duration * 60000);

    if (currentTime.getHours() >= 18) break; // End the day at 6 PM

    intervals.push({
      start: startTime,
      end: currentTime,
      focus: isFocus
    });

    isFocus = !isFocus;
  }

  // Generate category data
  const categories = [
    { name: "VSCode", seconds: Math.floor(Math.random() * 7200) + 3600 },
    { name: "Chrome", seconds: Math.floor(Math.random() * 5400) + 1800 },
    { name: "Notion", seconds: Math.floor(Math.random() * 3600) + 900 },
    { name: "Terminal", seconds: Math.floor(Math.random() * 2700) + 600 },
    { name: "Slack", seconds: Math.floor(Math.random() * 1800) + 300 },
    { name: "Break", seconds: breakMinutes * 60 }
  ];

  return {
    totalMinutes: focusMinutes + breakMinutes,
    focusMinutes,
    breakMinutes,
    intervals,
    categories: categories.sort((a, b) => b.seconds - a.seconds)
  };
};

// DonutChart Component
const DonutChart = ({ data }) => {
  const [hoveredSegment, setHoveredSegment] = useState(null);
  const total = Object.values(data).reduce((sum, val) => sum + val, 0);

  // Calculate segment positions
  const segments = [];
  let startAngle = -90;

  Object.entries(data).forEach(([label, value]) => {
    if (value <= 0) return;

    const angle = (value / total) * 360;
    const endAngle = startAngle + angle;

    // Calculate SVG arc path
    const radius = 80;
    const innerRadius = 48;

    const startRad = (startAngle * Math.PI) / 180;
    const endRad = (endAngle * Math.PI) / 180;

    const x1 = radius * Math.cos(startRad);
    const y1 = radius * Math.sin(startRad);
    const x2 = radius * Math.cos(endRad);
    const y2 = radius * Math.sin(endRad);

    const largeArcFlag = angle > 180 ? 1 : 0;

    const pathData = [
      `M ${innerRadius * Math.cos(startRad)} ${innerRadius * Math.sin(startRad)}`,
      `L ${x1} ${y1}`,
      `A ${radius} ${radius} 0 ${largeArcFlag} 1 ${x2} ${y2}`,
      `L ${innerRadius * Math.cos(endRad)} ${innerRadius * Math.sin(endRad)}`,
      `A ${innerRadius} ${innerRadius} 0 ${largeArcFlag} 0 ${innerRadius * Math.cos(startRad)} ${innerRadius * Math.sin(startRad)}`,
      'Z'
    ].join(' ');

    segments.push({
      label,
      pathData,
      startAngle,
      endAngle,
      value
    });

    startAngle = endAngle;
  });

  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours} h ${minutes} m`;
  };

  return (
    <div className="flex flex-col items-center justify-center w-full h-full">
      <svg width="180" height="180" viewBox="-100 -100 200 200">
        {segments.map((segment) => (
          <path
            key={segment.label}
            d={segment.pathData}
            fill={segment.label === "Focus" ? "#89B4FA" : "#74C7EC"}
            stroke={segment.label === hoveredSegment ? "white" : "transparent"}
            strokeWidth="1"
            onMouseEnter={() => setHoveredSegment(segment.label)}
            onMouseLeave={() => setHoveredSegment(null)}
            className={segment.label === hoveredSegment ? "cursor-pointer opacity-90" : "cursor-pointer"}
          >
            <title>{`${segment.label}: ${formatTime(segment.value)}`}</title>
          </path>
        ))}
        <circle cx="0" cy="0" r="48" fill="#1E1E2E" />
      </svg>
    </div>
  );
};

// Timeline Component
const Timeline = ({ intervals }) => {
  const formatHour = (hour) => {
    return hour.toString().padStart(2, '0');
  };

  // Create hour labels
  const hourLabels = [];
  for (let h = 0; h <= 24; h += 4) {
    hourLabels.push(h);
  }

  return (
    <div className="w-full h-16 py-2">
      <div className="relative w-full h-8 bg-gray-800 rounded">
        {intervals.map((interval, index) => {
          const startHour = interval.start.getHours() + interval.start.getMinutes() / 60;
          const endHour = interval.end.getHours() + interval.end.getMinutes() / 60;

          const startPercent = (startHour / 24) * 100;
          const width = ((endHour - startHour) / 24) * 100;

          return (
            <div
              key={index}
              className={`absolute h-8 ${interval.focus ? 'bg-blue-400' : 'bg-cyan-400'}`}
              style={{
                left: `${startPercent}%`,
                width: `${Math.max(0.5, width)}%`
              }}
              title={`${interval.start.toLocaleTimeString()} - ${interval.end.toLocaleTimeString()}`}
            />
          );
        })}
      </div>
      <div className="relative w-full h-6 mt-1">
        {hourLabels.map((hour) => (
          <div
            key={hour}
            className="absolute text-xs text-gray-400"
            style={{ left: `${(hour / 24) * 100}%`, transform: 'translateX(-50%)' }}
          >
            {formatHour(hour)}
          </div>
        ))}
      </div>
    </div>
  );
};

// Category Bar Component
const CategoryBar = ({ name, seconds, maxSeconds, color }) => {
  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return hours > 0 ? `${hours}h ${minutes}m` : `${minutes}m`;
  };

  const width = Math.max(5, (seconds / maxSeconds) * 70); // 70% of container max
  const displayName = name.length > 14 ? name.substring(0, 14) + '…' : name;

  return (
    <div className="flex items-center w-full h-6 mb-2">
      <div
        className="h-4 rounded"
        style={{ width: `${width}%`, backgroundColor: color }}
      />
      <div className="ml-4 text-sm whitespace-nowrap">
        {displayName} ({formatTime(seconds)})
      </div>
    </div>
  );
};

// Weekly and Monthly Views Components
const WeeklyView = ({ startDate }) => {
  // Generate data for each day of the week
  const weekData = [];
  const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  // Generate some sample data (only for Monday and Tuesday to match your example)
  const sampleData = [
    { day: 'Mon', hours: 1.4 },
    { day: 'Tue', hours: 2.2 },
    { day: 'Wed', hours: 0 },
    { day: 'Thu', hours: 0 },
    { day: 'Fri', hours: 0 },
    { day: 'Sat', hours: 0 },
    { day: 'Sun', hours: 0 }
  ];

  // Calculate average from days with data
  const nonZeroDays = sampleData.filter(day => day.hours > 0);
  const average = nonZeroDays.length > 0
    ? (nonZeroDays.reduce((sum, day) => sum + day.hours, 0) / nonZeroDays.length).toFixed(1)
    : 0;

  // Find max for scaling (at least 8 hours to match your image)
  const maxHours = 8;

  return (
    <div className="w-full p-4">
      <h2 className="text-xl font-semibold mb-4 ml-4">Daily Breakdown</h2>

      <div className="relative h-80">
        <h3 className="text-lg font-semibold text-center mb-6">Work Hours by Day</h3>

        {/* Y-axis labels and grid lines */}
        {[0, 2, 4, 6, 8].map(value => (
          <div key={value} className="absolute w-full" style={{ bottom: `${(value / maxHours) * 85}%` }}>
            <div className="absolute -left-6 text-gray-400">{value}</div>
            <div className="w-full h-px bg-gray-700" />
          </div>
        ))}

        {/* Average line with value */}
        <div
          className="absolute w-full border-t border-dashed border-white opacity-60 z-10"
          style={{ bottom: `${(average / maxHours) * 85}%` }}
        >
          <div className="absolute right-0 -top-5 text-white opacity-80">Average</div>
          <div className="absolute right-0 top-1 text-white opacity-80">{average}</div>
        </div>

        {/* Bars for each day */}
        <div className="absolute bottom-8 left-0 right-0 h-4/5 flex justify-between">
          {sampleData.map((dayData, index) => (
            <div key={index} className="relative flex flex-col items-center justify-end" style={{ width: `${100/7}%` }}>
              {dayData.hours > 0 && (
                <>
                  <div className="absolute -top-6 text-white text-sm">{dayData.hours}</div>
                  <div
                    className="w-4/5 bg-blue-400 rounded-t"
                    style={{ height: `${(dayData.hours / maxHours) * 85}%` }}
                  />
                </>
              )}
            </div>
          ))}
        </div>

        {/* X-axis labels */}
        <div className="absolute bottom-0 left-0 right-0 flex justify-between">
          {daysOfWeek.map((day, index) => (
            <div key={index} className="text-gray-300 pb-2" style={{ width: `${100/7}%`, textAlign: 'center' }}>
              {day}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const MonthlyView = ({ month, year }) => {
  // Generate data for each week of the month
  const monthData = [];
  const weeksInMonth = 5; // Max weeks to display

  // Find the first day of the month
  const firstDayOfMonth = new Date(year, month, 1);

  // Adjust to the Monday of that week
  const startOfFirstWeek = new Date(firstDayOfMonth);
  const dayOfWeek = firstDayOfMonth.getDay();
  startOfFirstWeek.setDate(firstDayOfMonth.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));

  for (let i = 0; i < weeksInMonth; i++) {
    const weekStart = new Date(startOfFirstWeek);
    weekStart.setDate(startOfFirstWeek.getDate() + (i * 7));

    // Don't include weeks starting in the future
    if (weekStart > new Date()) break;

    // Find week number
    const firstDayOfYear = new Date(weekStart.getFullYear(), 0, 1);
    const pastDaysOfYear = (weekStart - firstDayOfYear) / 86400000;
    const weekNum = Math.ceil((pastDaysOfYear + firstDayOfYear.getDay() + 1) / 7);

    // End date of the week
    const weekEnd = new Date(weekStart);
    weekEnd.setDate(weekStart.getDate() + 6);

    // Format dates for display
    const startDate = `${weekStart.getDate()}/${weekStart.getMonth() + 1}`;
    const endDate = `${weekEnd.getDate()}/${weekEnd.getMonth() + 1}`;

    // Generate random data for this week
    const totalMinutes = Math.floor(Math.random() * 1800) + 1200; // 20-50 hours weekly
    const focusMinutes = Math.floor(totalMinutes * (Math.random() * 0.3 + 0.6)); // 60-90% focus

    monthData.push({
      weekNum,
      dateRange: `${startDate} - ${endDate}`,
      totalMinutes,
      focusMinutes,
      breakMinutes: totalMinutes - focusMinutes
    });
  }

  return (
    <div className="w-full p-2">
      {monthData.map((week, index) => (
        <div key={index} className="flex items-center bg-gray-700 rounded p-3 mb-2">
          <div className="flex-shrink-0 w-16 text-center">
            <div className="text-sm font-medium">Week {week.weekNum}</div>
            <div className="text-xs text-gray-300">{week.dateRange}</div>
          </div>
          <div className="flex-grow mx-4">
            <div className="w-full h-4 bg-gray-800 rounded-full">
              <div
                className="h-4 bg-blue-400 rounded-full"
                style={{ width: `${(week.focusMinutes / week.totalMinutes) * 100}%` }}
              />
            </div>
          </div>
          <div className="flex-shrink-0 text-right">
            <div className="text-sm">{Math.floor(week.totalMinutes / 60)}h {week.totalMinutes % 60}m</div>
            <div className="text-xs text-gray-300">{Math.round((week.focusMinutes / week.totalMinutes) * 100)}% focus</div>
          </div>
        </div>
      ))}
    </div>
  );
};

// Main Dashboard Component
const FocusDashboard = () => {
  const [mode, setMode] = useState('day');
  const [data, setData] = useState(null);
  const [date, setDate] = useState(new Date());

  // Set up colors for category bars
  const categoryColors = [
    "#F2CDCD", "#DDB6F2", "#F5C2E7", "#E8A2AF", "#F28FAD",
    "#ABE9B3", "#FAE3B0", "#F8BD96", "#EE99A0", "#89DCEB"
  ];

  useEffect(() => {
    // Generate new data when mode or date changes
    setData(generateDummyData());
  }, [mode, date]);

  const changeDate = (offset) => {
    const newDate = new Date(date);
    if (mode === 'day') {
      newDate.setDate(newDate.getDate() + offset);
    } else if (mode === 'week') {
      newDate.setDate(newDate.getDate() + (7 * offset));
    } else {
      newDate.setMonth(newDate.getMonth() + offset);
    }

    // Don't allow dates in the future
    if (newDate <= new Date()) {
      setDate(newDate);
    }
  };

  // Get Monday of the current week
  const getMondayOfWeek = (d) => {
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is Sunday
    return new Date(d.setDate(diff));
  };

  const formatDate = () => {
    if (mode === 'day') {
      return date.toLocaleDateString('en-US', { year: 'numeric', month: '2-digit', day: '2-digit' });
    } else if (mode === 'week') {
      // Find the week number
      const firstDayOfYear = new Date(date.getFullYear(), 0, 1);
      const pastDaysOfYear = (date - firstDayOfYear) / 86400000;
      const weekNum = Math.ceil((pastDaysOfYear + firstDayOfYear.getDay() + 1) / 7);
      return `${date.getFullYear()} W${weekNum}`;
    } else {
      return date.toLocaleDateString('en-US', { year: 'numeric', month: 'short' });
    }
  };

  if (!data) return <div className="text-center p-4">Loading...</div>;

  return (
    <div className="flex flex-col w-full h-full p-4 bg-gray-900 text-gray-100 font-sans">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <h1 className="text-xl font-bold">Productivity Dashboard</h1>
        <div className="flex items-center space-x-2">
          <button
            className={`px-3 py-1 rounded ${mode === 'day' ? 'bg-blue-400 text-gray-900' : 'bg-gray-700'}`}
            onClick={() => setMode('day')}
          >
            Day
          </button>
          <button
            className={`px-3 py-1 rounded ${mode === 'week' ? 'bg-blue-400 text-gray-900' : 'bg-gray-700'}`}
            onClick={() => setMode('week')}
          >
            Week
          </button>
          <button
            className={`px-3 py-1 rounded ${mode === 'month' ? 'bg-blue-400 text-gray-900' : 'bg-gray-700'}`}
            onClick={() => setMode('month')}
          >
            Month
          </button>
          <div className="flex items-center ml-4">
            <button
              className="w-7 h-7 flex items-center justify-center bg-gray-700 rounded"
              onClick={() => changeDate(-1)}
            >
              ←
            </button>
            <div className="px-3 py-1 mx-1 bg-gray-700 rounded">
              {formatDate()}
            </div>
            <button
              className="w-7 h-7 flex items-center justify-center bg-gray-700 rounded"
              onClick={() => changeDate(1)}
            >
              →
            </button>
          </div>
        </div>
      </div>

      {/* Top Row - Summary and Donut */}
      <div className="flex gap-4 mb-4">
        {/* Summary Card */}
        <div className="flex-1 p-4 bg-gray-800 rounded-lg">
          <h2 className="text-lg font-bold mb-2">Summary</h2>
          <p className="mb-1">Work Hours: {Math.floor(data.totalMinutes / 60)} h {data.totalMinutes % 60} m</p>
          <p>Focus: {Math.round((data.focusMinutes / data.totalMinutes) * 100)}%</p>
        </div>

        {/* Donut Card */}
        <div className="flex-1 p-4 bg-gray-800 rounded-lg flex flex-col items-center">
          <h2 className="text-lg font-bold mb-2">Time Breakdown</h2>
          <DonutChart data={{
            "Focus": data.focusMinutes * 60,
            "Break": data.breakMinutes * 60
          }} />
        </div>
      </div>

      {/* View specific content */}
      {mode === 'day' && (
        <div className="p-4 mb-4 bg-gray-800 rounded-lg">
          <h2 className="text-lg font-bold mb-2">Calendar (sessions)</h2>
          <Timeline intervals={data.intervals} />
        </div>
      )}

      {mode === 'week' && (
        <div className="p-4 mb-4 bg-gray-800 rounded-lg">
          <h2 className="text-lg font-bold mb-2">Daily Breakdown</h2>
          <WeeklyView startDate={getMondayOfWeek(new Date(date))} />
        </div>
      )}

      {mode === 'month' && (
        <div className="p-4 mb-4 bg-gray-800 rounded-lg">
          <h2 className="text-lg font-bold mb-2">Weekly Breakdown</h2>
          <MonthlyView month={date.getMonth()} year={date.getFullYear()} />
        </div>
      )}

      {/* Categories */}
      <div className="flex-1 p-4 bg-gray-800 rounded-lg overflow-auto">
        <h2 className="text-lg font-bold mb-3">Top Categories</h2>
        <div className="space-y-1">
          {data.categories.map((category, index) => (
            <CategoryBar
              key={category.name}
              name={category.name}
              seconds={category.seconds}
              maxSeconds={data.categories[0].seconds}
              color={categoryColors[index % categoryColors.length]}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default FocusDashboard;
